"""Reproduce Stim Packs facts from BWAPI4.4.0 and the previously pinned OpenBW."""
import hashlib,json,re,sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else 'work/sources');tech=(root/'tech.cpp').read_text();engine=(root/'bwgame.h').read_text();actions=(root/'actions.h').read_text()
def body(s,n):
 s=re.sub(r'//[^\n]*','',s);m=re.search(re.escape(n)+r'\[[^\]]+\]\s*=\s*\{(.*?)\};',s,re.S);assert m,n;return m[1]
def nums(n):return list(map(int,re.findall(r'\d+',body(tech,n))))
names=re.findall(r'"([^"]*)"',body(tech,'typeNames'));i=names.index('Stim_Packs');producer=re.findall(r'\b\w+\b',body(tech,'whatResearches'))[i];a=actions[actions.index('bool action_stim_pack'):actions.index('bool action_cancel_nuke')];duration=int(re.search(r'stim_timer = (\d+)',a)[1]);cost=int(re.search(r'unit_deal_damage\(u, fp8::integer\((\d+)\)',a)[1]);cycle=int(re.search(r'cycle_counter >= (\d+)',engine)[1]);speed=engine[engine.index('fp8 get_modified_unit_speed'):engine.index('fp8 get_modified_unit_acceleration')];cooldown=engine[engine.index('int get_modified_weapon_cooldown'):engine.index('fp8 unit_halt_distance')];assert 'speed += speed / 2u' in speed and 'cooldown /= 2' in cooldown and 'cooldown < 5' in cooldown and 'u->hp <= fp8::integer(10)' in a;assert (duration,cost,cycle,producer)==(37,10,8,'Terran_Academy');assert 'Same as default gas cost' in tech
commit=json.loads((root/'openbw-commit.json').read_text())['sha'];out={'source':{'bwapiUrl':'https://github.com/bwapi/bwapi/blob/v4.4.0/bwapi/BWAPILIB/Source/TechType.cpp','openbwCommit':commit,'openbwUrls':[f'https://github.com/OpenBW/openbw/blob/{commit}/{n}'for n in ['bwgame.h','actions.h']],'sha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest()for n in ['tech.cpp','bwgame.h','actions.h']}},'technology':{'name':'Stim_Packs','title':'스팀팩','producer':producer.lower().replace('_','-'),'minerals':nums('defaultOreCost')[i],'gas':nums('defaultOreCost')[i],'frames':nums('defaultTimeCost')[i],'energy':nums('defaultEnergyCost')[i]},'healthCost':cost,'statusCycles':duration,'framesPerCycle':cycle,'speedNumerator':3,'speedDenominator':2,'cooldownDivisor':2,'minimumCooldownFrames':5}
Path('app/stark-rift/data/stim-original.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps(out,ensure_ascii=False))
